export const getListBuildingRoomsUrl = (building: number,
    params?: ListBuildingRoomsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/buildings/${building}/rooms?${stringifiedParams}` : `/buildings/${building}/rooms`
}

