/**
 * FR-21, second criterion: «entries are immutable; a correction is made
 * as a correcting entry».
 *
 * This route writes **nothing** to the visit. It writes a row to the
 * audit log naming it, and the register carries the two side by side —
 * which is what a numbered paper journal gives and an editable row does
 * not.
 *
 * The correction is free text and has to say something. There is no
 * structured «change this field to that value», and that is the point: a
 * correction that could be applied would be an edit with extra steps.
 *
 * Recording the exit and correcting the record are different rights. The
 * post records the exit; the correction asks for the register capability,
 * so an officer who mistyped a time reports it and the correcting entry
 * carries the name of whoever wrote it.
 * @summary Record a correcting entry against a visit
 */
export const correctGuestVisit = async (guestVisit: number,
    correctGuestVisitBody: CorrectGuestVisitBody, options?: Parameters<typeof apiFetch>[1]): Promise<correctGuestVisitResponse> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return apiFetch<correctGuestVisitResponse>(getCorrectGuestVisitUrl(guestVisit),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(correctGuestVisitBody)
  }
);}





